pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Send 1 ether to the contract via fallback
        vm.deal(address(this), 1 ether);
        (bool sent, ) = address(c).call{value: 1 ether}("");
        require(sent, "fallback failed");
        // Call withdrawAll from owner (address(this))
        vm.prank(address(this));
        c.withdrawAll(address(this));
        // After the call, reference keeps code; buggy selfdestruct removes it
        // Assert that the contract still has code (reference holds, bug fails)
        uint256 codeSize;
        assembly {
            codeSize := extcodesize(c)
        }
        assertTrue(codeSize > 0);
    }
}

