pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Send 1 ether to the contract via fallback
        vm.deal(address(this), 1 ether);
        address(c).call{value: 1 ether}("");

        // Call withdrawAll from owner (address(this)) sending to address(1)
        c.withdrawAll(address(1));

        // After the call, try to call a getter on the contract
        bool ok;
        try c.owner() returns (address) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "Contract should still exist and return owner");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Fund contract with 1 ether
        vm.deal(address(c), 1 ether);

        // Record owner balance before
        uint256 balanceBefore = address(this).balance;

        // Owner calls withdrawAll with recipient = address(this)
        vm.prank(address(this));
        c.withdrawAll(address(this));

        // After call: in reference, balance increases by 1 ether; in buggy, selfdestruct sends but destroys contract
        uint256 balanceAfter = address(this).balance;

        // Assert that the owner's balance increased (true for reference, false for buggy)
        assertTrue(balanceAfter > balanceBefore);
    }
}

