import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Send 0 ether to the contract via fallback (optional, but included for realism)
        address(c).call{value: 0}("");
        // Call withdrawAll from owner (address(this))
        c.withdrawAll(address(this));
        // After reference: contract code exists; after bug: selfdestruct removes it
        uint256 codeSize;
        assembly {
            codeSize := extcodesize(c)
        }
        assertTrue(codeSize > 0);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Fund the contract with 1 ether
        vm.deal(address(this), 1 ether);
        (bool success,) = address(c).call{value: 1 ether}("");
        require(success);

        // Non-owner alice attempts to withdraw
        address alice = address(0x1234);
        vm.deal(alice, 0);
        vm.prank(alice);

        bool ok;
        try c.withdrawAll(alice) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: reverts (ok=false). Bug: succeeds (ok=true).
        assertTrue(ok == false);
    }
}
